HIST_B = [(2025, 2440, 114250), (2024, 2320, 112010), (2023, 2180, 109810), (2022, 2110, 107660), (2021, 2070, 105600), (2020, 2200, 104510), (2019, 2130, 102470), (2018, 2060, 100460), (2017, 1740, 98490), (2016, 1680, 96560)]
