PROP13_FACTOR = 0.020
RATE_A = 0.01335
RATE_B = 0.02135
SALE_COST_PCT = 0.050
RECORDING = 260
RENT_A_MO_BASE = 6500
VACANCY = 0.05
MGMT = 0.08
MAINT_A = {"low": 8000, "base": 15000, "high": 30000}
MAINT_B = {"low": 15000, "base": 25000, "high": 40000}
PROP_H_B = 750
ESTATE_2026 = 15000000
ESTATE_2027 = 15480000


def r10(x: float) -> int:
    return int(round(x / 10.0) * 10)


def money(x: float) -> str:
    return "$" + format(r10(x), ",d")


def project(value: float, rate: float, years: int) -> float:
    return value * ((1.0 + rate) ** years)


def prop19_cap(transfer_year: int) -> float:
    return 1044586.0 * ((1.0 + PROP19_INDEX) ** max(0, transfer_year - 2026))


def av_after_transfer(fmv: float, av_prior: float, cap: float, claim: bool) -> float:
    if not claim:
        return fmv
    if fmv - av_prior <= cap:
        return av_prior
    return fmv - cap


def transfer_sale(transfer_year: int, growth: float) -> dict:
    years = transfer_year - 2026
    fmv = project(A_VALUE_2026, growth, years)
    price = fmv
    costs = price * SALE_COST_PCT
    dtt = math.ceil(price / 500.0) * 0.55
    gain = max(0.0, price - costs - fmv)
    net = price - costs - dtt - RECORDING
    return {"fmv": fmv, "price": price, "costs": costs, "dtt": dtt, "gain": gain, "net": net}


def rent_flow(transfer_year: int, growth: float, rent_growth: float, years_held: int) -> dict:
    fmv = project(A_VALUE_2026, growth, transfer_year - 2026)
    tax = fmv * RATE_A
    rent0 = project(RENT_A_MO_BASE * 12.0, rent_growth, transfer_year - 2026)
    gross = rent0 * ((1.0 + rent_growth) ** years_held)
    vac = gross * VACANCY
    mgmt = (gross - vac) * MGMT
    ins = project(INS_YR, INFLATION["base"], transfer_year - 2026 + years_held)
    water = project(150.0 * 12.0, INFLATION["base"], transfer_year - 2026 + years_held)
    maint = project(MAINT_A["base"], INFLATION["base"], transfer_year - 2026 + years_held)
    net = gross - vac - mgmt - tax - ins - water - maint
    return {"fmv": fmv, "tax": tax, "gross": gross, "net": net}


def live_flow(transfer_year: int, growth: float, rent_growth: float, claim: bool) -> dict:
    years = transfer_year - 2026
    fmv = project(A_VALUE_2026, growth, years)
    cap = prop19_cap(transfer_year)
    av_prior = project(A_AV_2026, PROP13_FACTOR, years)
    av = av_after_transfer(fmv, av_prior, cap, claim)
    tax = av * RATE_A
    ins = project(INS_YR, INFLATION["base"], years)
    water = project(150.0 * 12.0, INFLATION["base"], years)
    elec = -project(20.0 * 12.0, INFLATION["base"], years)
    maint = MAINT_A["base"]
    imputed = project(RENT_A_MO_BASE * 12.0, rent_growth, years)
    net_cost = tax + ins + water + elec + maint - imputed
    return {"fmv": fmv, "cap": cap, "av": av, "tax": tax, "imputed": imputed, "net_cost": net_cost}


def stage_math(amount: float, months: int, treasury: float, equity: float, renewal: float) -> dict:
    mt = (1.0 + treasury) ** (1.0 / 12.0) - 1.0
    mr = (1.0 + renewal) ** (1.0 / 12.0) - 1.0
    me = (1.0 + equity) ** (1.0 / 12.0) - 1.0
    installment = amount / months
    reserve = amount
    shares = 0.0
    index = 1.0
    for month in range(1, months + 1):
        rate = mt if month <= months / 2 else mr
        reserve *= 1.0 + rate
        purchase = min(reserve, installment)
        reserve -= purchase
        shares += purchase / index
        index *= 1.0 + me
    return {"ending": shares * index + reserve, "reserve": reserve}


def staged_terminal(amount: float, months: int, horizon_years: float, treasury: float, equity: float, renewal: float) -> float:
    staged = stage_math(amount, months, treasury, equity, renewal)
    remaining = max(0.0, horizon_years - months / 12.0)
    return staged["ending"] * ((1.0 + equity) ** remaining)


def crash_compare(amount: float, months: int, crash_pct: float, crash_month: int) -> dict:
    shock = 1.0 - crash_pct / 100.0
    installment = amount / months
    reserve = amount
    shares = 0.0
    index = 1.0
    immediate_loss = 0.0
    phased_loss = 0.0
    applied = False
    for month in range(1, months + 1):
        if crash_month == month:
            immediate_loss = amount * index * (1 - shock)
            phased_loss = shares * index * (1 - shock)
            index *= shock
            applied = True
        purchase = min(reserve, installment)
        reserve -= purchase
        shares += purchase / index
    if not applied:
        immediate_loss = amount * index * (1 - shock)
        phased_loss = shares * index * (1 - shock)
        index *= shock
    return {"immediate_loss": immediate_loss, "phased_loss": phased_loss, "immediate_end": amount * index, "phased_end": shares * index + reserve}


def monte_carlo(n_draws: int = 2000, horizon: int = 20, seed: int = 20261117) -> dict:
    state = seed

    def rnd() -> float:
        nonlocal state
        state = (1103515245 * state + 12345) % (2 ** 31)
        return state / float(2 ** 31)

    def normal() -> float:
        u1 = max(1e-9, rnd())
        u2 = rnd()
        return math.sqrt(-2.0 * math.log(u1)) * math.cos(2.0 * math.pi * u2)

    net = transfer_sale(2045, GROWTH["base"])["net"]
    paths = {"immediate": [], "stage24": [], "stage36": [], "rent": []}
    rent_case = rent_flow(2045, GROWTH["base"], RENT_GROWTH["base"], horizon)
    for _ in range(n_draws):
        terminal_factor = 1.0
        for _yr in range(horizon):
            u = rnd()
            if u < 0.05:
                mu, sd = -0.28, 0.20
            elif u < 0.15:
                mu, sd = -0.02, 0.15
            elif u < 0.32:
                mu, sd = 0.03, 0.18
            else:
                mu, sd = 0.085, 0.13
            r = max(-0.60, min(0.45, mu + sd * normal()))
            terminal_factor *= 1.0 + r
        ty = max(0.0, TREASURY["base"] + 0.010 * normal())
        ry = max(0.0, RENEWAL["base"] + 0.010 * normal())
        paths["immediate"].append(net * terminal_factor)
        for key, months in (("stage24", 24), ("stage36", 36)):
            staged = stage_math(net, months, ty, 0.0, ry)
            remaining = max(0.0, horizon - months / 12.0)
            f2 = 1.0
            for _yr in range(int(remaining)):
                u = rnd()
                if u < 0.05:
                    mu, sd = -0.28, 0.20
                elif u < 0.15:
                    mu, sd = -0.02, 0.15
                elif u < 0.32:
                    mu, sd = 0.03, 0.18
                else:
                    mu, sd = 0.085, 0.13
                r = max(-0.60, min(0.45, mu + sd * normal()))
                f2 *= 1.0 + r
            paths[key].append(staged["ending"] * f2)
        flows = rent_case["net"] * ((1.0 + INFLATION["base"]) ** (horizon / 2.0))
        fv_flows = flows * horizon * 1.25
        home_end = project(rent_case["fmv"], GROWTH["base"], horizon) * (1.0 - SALE_COST_PCT - 0.0011)
        paths["rent"].append(fv_flows + home_end)

    def quantiles(values):
        s = sorted(values)
        def q(p: float) -> float:
            idx = min(len(s) - 1, max(0, int(p * len(s))))
            return s[idx]
        return {"p5": q(0.05), "p25": q(0.25), "p50": q(0.50), "p75": q(0.75), "p95": q(0.95)}

    return {key: quantiles(vals) for key, vals in paths.items()}


