            (["Live in Property A (family-home claim, long-term occupancy)", f"Annual tax about {money(live_claim['tax'])} even with the claim, plus insurance, water and maintenance; imputed rent about {money(live_claim['imputed'])} per year. Net lifestyle cost about {money(live_claim['net_cost'])} per year versus the status-quo housing at Property B.", "Signed occupancy intention; assessor eligibility confirmation; homeowners' exemption within one year; claim filed within the statutory window."], STATUS["rule"], ["boe_prop19", "ca_rtc63", "ca_rtc218"]),
